const te=new TextEncoder();
const b64=a=>btoa(String.fromCharCode(...new Uint8Array(a))).replace(/=/g,"").replaceAll("+","-").replaceAll("/","_");
const rnd=n=>b64(crypto.getRandomValues(new Uint8Array(n)));
const sha=async x=>b64(await crypto.subtle.digest("SHA-256",te.encode(x)));
function normalizePhone(value){let p=String(value||"").trim().replaceAll(" ","").replaceAll("-","").replaceAll("(","").replaceAll(")","").replaceAll(".","");if(/^0[0-9]{9}$/.test(p))p="+256"+p.slice(1);else if(/^[0-9]{9}$/.test(p))p="+256"+p;else if(/^256[0-9]{9}$/.test(p))p="+"+p;else if(/^[+][1-9][0-9]{7,14}$/.test(p))return p;return /^[+]256[0-9]{9}$/.test(p)?p:null}
async function pass(p,s){let k=await crypto.subtle.importKey("raw",te.encode(p),"PBKDF2",false,["deriveBits"]);return b64(await crypto.subtle.deriveBits({name:"PBKDF2",salt:te.encode(s),iterations:100000,hash:"SHA-256"},k,256))}
async function session(uid,e){let t=rnd(32);await e.DB.prepare("INSERT INTO sessions(id_hash,user_id,expires_at) VALUES(?,?,?)").bind(await sha(t),uid,new Date(Date.now()+604800000).toISOString()).run();let u=await e.DB.prepare("SELECT id,full_name,phone_e164,referral_code FROM users WHERE id=?").bind(uid).first();return out({user:u},200,{"set-cookie":"ph_session="+t+"; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=604800"})}
function sessionToken(req){return req.headers.get("cookie")?.split(";").map(x=>x.trim()).find(x=>x.startsWith("ph_session="))?.slice(11)||null}
async function me(req,e){let t=sessionToken(req);if(!t)return null;return e.DB.prepare("SELECT u.id,u.full_name,u.phone_e164,u.referral_code FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.id_hash=? AND s.expires_at>? AND u.status='active'").bind(await sha(t),new Date().toISOString()).first()}
async function marzRequest(path,method="GET",payload=null,e){if(!e.MARZPAY_API_KEY||!e.MARZPAY_API_SECRET)throw new Error("MarzPay credentials are not configured.");const auth=btoa(e.MARZPAY_API_KEY+":"+e.MARZPAY_API_SECRET);const response=await fetch("https://wallet.wearemarz.com/api/v1"+path,{method,headers:{"authorization":"Basic "+auth,"content-type":"application/json","accept":"application/json"},body:payload?JSON.stringify(payload):undefined,signal:AbortSignal.timeout(15000)});const raw=await response.text();let data;try{data=JSON.parse(raw)}catch{throw new Error("MarzPay returned an unreadable response.");}if(!response.ok||data.status==="error")throw new Error(String(data.message||"MarzPay request failed").slice(0,220));return data}
async function verifyMarzTransaction(uuid,e){const result=await marzRequest("/transactions/"+encodeURIComponent(uuid),"GET",null,e);return result?.data||result}
async function creditReferralRewards(depositorId,depositRequestId,amount,e){const rates=[20,5,2];let childId=depositorId;for(let i=0;i<rates.length;i++){const parent=await e.DB.prepare("SELECT referred_by_user_id FROM users WHERE id=?").bind(childId).first();const parentId=parent?.referred_by_user_id;if(!parentId)break;const reward=Math.floor(Number(amount)*rates[i]/100);if(reward>0){await e.DB.prepare("INSERT OR IGNORE INTO ledger_entries(id,user_id,entry_type,amount_ugx,direction,status,provider_reference,description,posted_at) VALUES(?,?, 'referral_earning',?,'credit','posted',?,?,CURRENT_TIMESTAMP)").bind("marzpay-referral-"+depositRequestId+"-L"+(i+1),parentId,reward,"marzpay-referral:"+depositRequestId+":L"+(i+1),"Verified deposit referral reward · Level "+(i+1)).run();}childId=parentId;}}
async function handleMarzCallback(req,e){let body;try{body=await req.json()}catch{return out({error:"Invalid callback JSON."},400)}const tx=body?.transaction;if(!tx||typeof tx.reference!=="string"||typeof tx.uuid!=="string")return out({error:"Callback transaction details are missing."},400);const request=await e.DB.prepare("SELECT * FROM payment_requests WHERE id=?").bind(tx.reference).first();if(!request)return out({ok:true,ignored:true});if(!["collection","disbursement"].includes(request.kind))return out({error:"Unknown transaction type."},400);let verified;try{verified=await verifyMarzTransaction(tx.uuid,e)}catch(err){console.error("MarzPay callback verification failed",err);return out({error:"Could not verify callback with MarzPay."},503)}const vtx=verified?.transaction||verified?.data?.transaction||{};const collection=verified?.collection||verified?.data?.collection||{};const disbursement=verified?.disbursement||verified?.data?.disbursement||verified?.send_money||verified?.data?.send_money||{};const actualReference=String(vtx.reference||"");const status=String(vtx.status||"").toLowerCase();const finalSuccess=["completed","successful","success"].includes(status);const finalFailure=["failed","failure","cancelled","canceled"].includes(status);const amountObj=vtx.amount||collection.amount||disbursement.amount;const actualAmount=Number(amountObj?.raw??amountObj?.amount??NaN);const expectedAmount=request.kind==="disbursement"?Number(request.amount_ugx)-Math.floor(Number(request.amount_ugx)*.15):Number(request.amount_ugx);const actualPhone=String(vtx.phone_number||collection.phone_number||disbursement.phone_number||"");if(actualReference!==request.id||!Number.isFinite(actualAmount)||actualAmount!==expectedAmount||(actualPhone&&actualPhone!==request.phone_e164))return out({error:"MarzPay transaction details do not match this request."},409);if(!finalSuccess&&!finalFailure)return out({ok:true,pending:true});if(request.status==="confirmed"||request.status==="failed"||request.status==="cancelled")return out({ok:true,duplicate:true});if(request.kind==="collection"){if(finalSuccess){if(request.purpose==="product_purchase"&&request.product_purchase_id){await e.DB.batch([e.DB.prepare("UPDATE payment_requests SET status='confirmed',updated_at=CURRENT_TIMESTAMP,provider_reference=COALESCE(provider_reference,?) WHERE id=? AND status IN ('created','pending')").bind(tx.uuid,request.id),e.DB.prepare("UPDATE product_purchases SET status='confirmed',updated_at=CURRENT_TIMESTAMP,provider_reference=COALESCE(provider_reference,?) WHERE id=? AND status='pending'").bind(tx.uuid,request.product_purchase_id)]);}else{await e.DB.batch([e.DB.prepare("UPDATE payment_requests SET status='confirmed',updated_at=CURRENT_TIMESTAMP,provider_reference=COALESCE(provider_reference,?) WHERE id=? AND status IN ('created','pending')").bind(tx.uuid,request.id),e.DB.prepare("INSERT OR IGNORE INTO ledger_entries(id,user_id,entry_type,amount_ugx,direction,status,provider_reference,description,posted_at) VALUES(?,?, 'mobile_money_deposit',?,'credit','posted',?,?,CURRENT_TIMESTAMP)").bind("marzpay-deposit-"+request.id,request.user_id,request.amount_ugx,"marzpay:collection:"+request.id,"MarzPay mobile-money deposit")]);await creditReferralRewards(request.user_id,request.id,request.amount_ugx,e);}}else{let failedStatus=status==="cancelled"||status==="canceled"?"cancelled":"failed";await e.DB.prepare("UPDATE payment_requests SET status=?,updated_at=CURRENT_TIMESTAMP,provider_reference=COALESCE(provider_reference,?) WHERE id=? AND status IN ('created','pending')").bind(failedStatus,tx.uuid,request.id).run();if(request.purpose==="product_purchase"&&request.product_purchase_id)await e.DB.prepare("UPDATE product_purchases SET status=?,updated_at=CURRENT_TIMESTAMP,provider_reference=COALESCE(provider_reference,?) WHERE id=? AND status='pending'").bind(failedStatus,tx.uuid,request.product_purchase_id).run();}}else{if(finalSuccess){await e.DB.batch([e.DB.prepare("UPDATE payment_requests SET status='confirmed',updated_at=CURRENT_TIMESTAMP,provider_reference=COALESCE(provider_reference,?) WHERE id=? AND status IN ('created','pending')").bind(tx.uuid,request.id),e.DB.prepare("INSERT OR IGNORE INTO ledger_entries(id,user_id,entry_type,amount_ugx,direction,status,provider_reference,description,posted_at) VALUES(?,?, 'mobile_money_withdrawal',?,'debit','posted',?,?,CURRENT_TIMESTAMP)").bind("marzpay-withdraw-"+request.id,request.user_id,request.amount_ugx,"marzpay:withdrawal:"+request.id,"MarzPay mobile-money withdrawal (gross amount)")]);}else{await e.DB.prepare("UPDATE payment_requests SET status=?,updated_at=CURRENT_TIMESTAMP,provider_reference=COALESCE(provider_reference,?) WHERE id=? AND status IN ('created','pending')").bind(status==="cancelled"||status==="canceled"?"cancelled":"failed",tx.uuid,request.id).run();}}return out({ok:true})}
