if(p==="/api/register"&&req.method==="POST"){let b=await req.json(),n=String(b.name||"").trim(),ph=normalizePhone(b.phone),pw=String(b.password||"");if(n.length<2||n.length>100||!ph||pw.length<10||pw.length>128)return out({error:"Enter your name, a valid Ugandan phone number (e.g. 0771234567 or +256771234567), and password of 10–128 characters."},400);let ref=String(b.referralCode||"").trim().toUpperCase(),parent=null;if(ref){let q=await e.DB.prepare("SELECT id FROM users WHERE referral_code=?").bind(ref).first();if(!q)return out({error:"Referral code not found."},400);parent=q.id}let id=crypto.randomUUID(),code="PH"+rnd(6).toUpperCase(),salt=rnd(16),passwordHash=salt+"."+await pass(pw,salt);try{await e.DB.batch([e.DB.prepare("INSERT INTO users(id,full_name,phone_e164,password_hash,referral_code,referred_by_user_id) VALUES(?,?,?,?,?,?)").bind(id,n,ph,passwordHash,code,parent),e.DB.prepare("INSERT INTO ledger_entries(id,user_id,entry_type,amount_ugx,direction,status,provider_reference,description,posted_at) VALUES(?,?,?,5000,'credit','posted',?,?,CURRENT_TIMESTAMP)").bind("welcome-"+id,id,"welcome_bonus","welcome-bonus:"+id,"Peak Holdings welcome bonus")])}catch(err){console.error("Peak Holdings registration batch failed",err);let existing=await e.DB.prepare("SELECT id FROM users WHERE phone_e164=?").bind(ph).first().catch(()=>null);if(existing)return out({error:"This phone number is already registered. Please log in."},409);return out({error:"We couldn’t save your account. Please try again."},500)}return session(id,e)}
