if(p==="/api/dashboard"){let u=await me(req,e);if(!u)return out({error:"Not signed in"},401);let summary=await e.DB.prepare("SELECT COALESCE(SUM(CASE WHEN direction='credit' THEN amount_ugx ELSE -amount_ugx END),0) AS balance,COALESCE(SUM(CASE WHEN direction='credit' AND entry_type IN ('deposit','mobile_money_deposit') THEN amount_ugx ELSE 0 END),0) AS total_deposited,COALESCE(SUM(CASE WHEN direction='credit' AND entry_type IN ('earning','investment_return','daily_earning') THEN amount_ugx ELSE 0 END),0) AS total_earned,COALESCE(SUM(CASE WHEN direction='credit' AND entry_type='referral_earning' THEN amount_ugx ELSE 0 END),0) AS referral_earnings,COALESCE(SUM(CASE WHEN direction='debit' AND entry_type IN ('withdrawal','mobile_money_withdrawal') THEN amount_ugx ELSE 0 END),0) AS total_withdrawn,COALESCE(SUM(CASE WHEN direction='credit' AND entry_type IN ('earning','investment_return','daily_earning') AND date(COALESCE(posted_at,created_at))=date('now') THEN amount_ugx ELSE 0 END),0) AS today_earnings,COALESCE(SUM(CASE WHEN direction='credit' AND entry_type='welcome_bonus' THEN amount_ugx ELSE 0 END),0) AS welcome_bonus FROM ledger_entries WHERE user_id=? AND status='posted'").bind(u.id).first();return out({summary:summary||{balance:0,total_deposited:0,total_earned:0,referral_earnings:0,total_withdrawn:0,today_earnings:0,welcome_bonus:0}})}
if(p==="/api/referrals"){let u=await me(req,e);if(!u)return out({error:"Not signed in"},401);let referrals=(await e.DB.prepare("SELECT id,CASE WHEN phone_e164 LIKE '+256%' THEN '+256••••'||substr(phone_e164,-4) ELSE '••••'||substr(phone_e164,-4) END AS phone_masked,created_at,COALESCE((SELECT SUM(amount_ugx) FROM ledger_entries le WHERE le.user_id=users.id AND le.status='posted' AND le.direction='credit' AND le.entry_type IN ('deposit','mobile_money_deposit')),0) AS verified_deposits FROM users WHERE referred_by_user_id=? ORDER BY created_at DESC LIMIT 100").bind(u.id).all()).results||[];return out({count:referrals.length,total_verified_deposits:referrals.reduce((n,r)=>n+Number(r.verified_deposits||0),0),referrals})}
if(p==="/api/ledger"){let u=await me(req,e);if(!u)return out({error:"Not signed in"},401);let entries=(await e.DB.prepare("SELECT id,entry_type,amount_ugx,direction,status,description,created_at,posted_at FROM ledger_entries WHERE user_id=? ORDER BY created_at DESC LIMIT 50").bind(u.id).all()).results||[];return out({entries})}
if(p==="/api/change-password"&&req.method==="POST"){let u=await me(req,e);if(!u)return out({error:"Not signed in"},401);let b=await req.json(),current=String(b.currentPassword||""),next=String(b.newPassword||"");if(next.length<10||next.length>128)return out({error:"New password must be 10–128 characters."},400);let row=await e.DB.prepare("SELECT password_hash FROM users WHERE id=? AND status='active'").bind(u.id).first();if(!row)return out({error:"Account not available."},401);let [salt,hash]=String(row.password_hash||"").split(".");if(!salt||hash!==await pass(current,salt))return out({error:"Current password is incorrect."},401);let newSalt=rnd(16),newHash=newSalt+"."+await pass(next,newSalt),token=sessionToken(req);await e.DB.prepare("UPDATE users SET password_hash=? WHERE id=?").bind(newHash,u.id).run();if(token)await e.DB.prepare("DELETE FROM sessions WHERE user_id=? AND id_hash<>?").bind(u.id,await sha(token)).run();else await e.DB.prepare("DELETE FROM sessions WHERE user_id=?").bind(u.id).run();return out({ok:true})}
