if(p==="/api/deposit-request"&&req.method==="POST"){let u=await me(req,e);if(!u)return out({error:"Please log in first."},401);let b=await req.json(),amount=Number(b.amount),phone=normalizePhone(b.phone),provider=String(b.provider||"").toLowerCase();if(!Number.isSafeInteger(amount)||amount<15000||amount>10000000)return out({error:"MarzPay supports deposits from UGX 15,000 up to UGX 10,000,000."},400);if(!phone||!["mtn","airtel"].includes(provider))return out({error:"Enter a valid mobile-money phone and choose MTN or Airtel."},400);let id=crypto.randomUUID();await e.DB.prepare("INSERT INTO payment_requests(id,user_id,kind,amount_ugx,phone_e164,provider,status) VALUES(?,?, 'collection',?,?,?,'created')").bind(id,u.id,amount,phone,provider).run();try{let result=await marzRequest("/collect-money","POST",{amount,phone_number:phone,country:"UG",reference:id,description:"Peak Holdings deposit",callback_url:new URL("/api/marzpay/callback",new URL(req.url).origin).toString(),metadata:[{peakHoldingsRequestId:id}]},e);let tx=result?.data?.transaction||{};if(result.status!=="success"||!tx.uuid||String(tx.reference||"")!==id)throw new Error(result.message||"MarzPay did not accept the collection.");await e.DB.prepare("UPDATE payment_requests SET status='pending',provider_reference=?,updated_at=CURRENT_TIMESTAMP WHERE id=? AND status='created'").bind(tx.uuid,id).run();return out({ok:true,id,status:"pending",message:"Payment prompt initiated. Approve it on your phone; your balance updates only after MarzPay verifies success."})}catch(err){console.error("MarzPay collection initiation failed",err);await e.DB.prepare("UPDATE payment_requests SET status='failed',updated_at=CURRENT_TIMESTAMP WHERE id=? AND status='created'").bind(id).run();return out({error:"MarzPay could not start this payment. Please check the number and try again."},502)}}
if(p==="/api/purchase-request"&&req.method==="POST"){let u=await me(req,e);if(!u)return out({error:"Please log in first."},401);let b=await req.json(),productId=Number(b.productId),phone=normalizePhone(b.phone),provider=String(b.provider||"").toLowerCase();if(!Number.isSafeInteger(productId)||!phone||!["mtn","airtel"].includes(provider))return out({error:"Choose a valid machine, mobile-money phone, and network."},400);let product=await e.DB.prepare("SELECT id,name,principal_ugx,terms_status FROM products WHERE id=?").bind(productId).first();if(!product)return out({error:"Machine not found."},404);let deposited=await e.DB.prepare("SELECT COALESCE(SUM(amount_ugx),0) AS n FROM ledger_entries WHERE user_id=? AND status='posted' AND direction='credit' AND entry_type IN ('deposit','mobile_money_deposit')").bind(u.id).first();if(Number(deposited?.n||0)<15000)return out({error:"Please make a confirmed deposit of at least UGX 15,000 before requesting a machine purchase."},409);if(product.terms_status==="disabled")return out({error:"This machine is not currently open for purchase."},409);if(b.acceptUnverifiedTerms!==true)return out({error:"Please acknowledge that machine terms and advertised income are unverified before purchasing."},400);let id=crypto.randomUUID(),paymentId=crypto.randomUUID();await e.DB.prepare("INSERT INTO product_purchases(id,user_id,product_id,amount_ugx,phone_e164,provider,status) VALUES(?,?,?,?,?,?,'pending')").bind(id,u.id,productId,product.principal_ugx,phone,provider).run();await e.DB.prepare("INSERT INTO payment_requests(id,user_id,kind,amount_ugx,phone_e164,provider,status,purpose,product_purchase_id) VALUES(?,?, 'collection',?,?,?,'created','product_purchase',?)").bind(paymentId,u.id,product.principal_ugx,phone,provider,id).run();try{let result=await marzRequest("/collect-money","POST",{amount:Number(product.principal_ugx),phone_number:phone,country:"UG",reference:paymentId,description:"Peak Holdings machine purchase: "+product.name,callback_url:new URL("/api/marzpay/callback",new URL(req.url).origin).toString(),metadata:[{peakHoldingsRequestId:paymentId,productPurchaseId:id}]},e);let tx=result?.data?.transaction||{};if(result.status!=="success"||!tx.uuid||String(tx.reference||"")!==paymentId)throw new Error(result.message||"MarzPay did not accept the collection.");await e.DB.batch([e.DB.prepare("UPDATE payment_requests SET status='pending',provider_reference=?,updated_at=CURRENT_TIMESTAMP WHERE id=? AND status='created'").bind(tx.uuid,paymentId),e.DB.prepare("UPDATE product_purchases SET provider_reference=?,updated_at=CURRENT_TIMESTAMP WHERE id=? AND status='pending'").bind(tx.uuid,id)]);return out({ok:true,id,status:"pending",message:"MTN/Airtel payment prompt started. Approve it on your phone. The machine activates only after MarzPay confirms successful payment."})}catch(err){console.error("MarzPay machine purchase initiation failed",err);await e.DB.batch([e.DB.prepare("UPDATE payment_requests SET status='failed',updated_at=CURRENT_TIMESTAMP WHERE id=? AND status='created'").bind(paymentId),e.DB.prepare("UPDATE product_purchases SET status='failed',updated_at=CURRENT_TIMESTAMP WHERE id=? AND status='pending'").bind(id)]);return out({error:"MarzPay could not start this machine payment. No machine was activated; please try again."},502)}}
if(p==="/api/withdraw-request"&&req.method==="POST"){let u=await me(req,e);if(!u)return out({error:"Please log in first."},401);let b=await req.json(),amount=Number(b.amount),phone=normalizePhone(b.phone),provider=String(b.provider||"").toLowerCase();if(!Number.isSafeInteger(amount)||amount<5000||amount>10000000)return out({error:"Withdrawal must be between UGX 5,000 and UGX 10,000,000."},400);if(!phone||!["mtn","airtel"].includes(provider))return out({error:"Enter a valid mobile-money phone and choose MTN or Airtel."},400);let deposited=await e.DB.prepare("SELECT COALESCE(SUM(amount_ugx),0) AS n FROM ledger_entries WHERE user_id=? AND status='posted' AND direction='credit' AND entry_type IN ('deposit','mobile_money_deposit')").bind(u.id).first();if(Number(deposited?.n||0)<15000)return out({error:"Withdrawals unlock only after a confirmed deposit of at least UGX 15,000."},409);let purchase=await e.DB.prepare("SELECT id FROM product_purchases WHERE user_id=? AND status='confirmed' LIMIT 1").bind(u.id).first();if(!purchase)return out({error:"Withdrawals unlock after at least one machine purchase is confirmed."},409);let sums=await e.DB.prepare("SELECT COALESCE(SUM(CASE WHEN direction='credit' THEN amount_ugx ELSE -amount_ugx END),0) AS balance FROM ledger_entries WHERE user_id=? AND status='posted'").bind(u.id).first();let reserved=await e.DB.prepare("SELECT COALESCE(SUM(amount_ugx),0) AS n FROM payment_requests WHERE user_id=? AND kind='disbursement' AND status IN ('created','pending')").bind(u.id).first();if(amount>Number(sums?.balance||0)-Number(reserved?.n||0))return out({error:"Insufficient available balance after pending withdrawal requests."},409);let id=crypto.randomUUID(),net=amount-Math.floor(amount*.15);await e.DB.prepare("INSERT INTO payment_requests(id,user_id,kind,amount_ugx,phone_e164,provider,status) VALUES(?,?, 'disbursement',?,?,?,'created')").bind(id,u.id,amount,phone,provider).run();try{let result=await marzRequest("/send-money","POST",{amount:net,phone_number:phone,country:"UG",reference:id,description:"Peak Holdings withdrawal",callback_url:new URL("/api/marzpay/callback",new URL(req.url).origin).toString(),metadata:[{peakHoldingsRequestId:id}]},e);let tx=result?.data?.transaction||{};if(result.status!=="success"||!tx.uuid||String(tx.reference||"")!==id)throw new Error(result.message||"MarzPay did not accept the payout.");await e.DB.prepare("UPDATE payment_requests SET status='pending',provider_reference=?,updated_at=CURRENT_TIMESTAMP WHERE id=? AND status='created'").bind(tx.uuid,id).run();return out({ok:true,id,status:"pending",gross_ugx:amount,deduction_ugx:Math.floor(amount*.15),net_ugx:net,message:"Withdrawal submitted to MarzPay. It remains pending until MarzPay confirms the payout."})}catch(err){console.error("MarzPay disbursement initiation failed",err);await e.DB.prepare("UPDATE payment_requests SET status='failed',updated_at=CURRENT_TIMESTAMP WHERE id=? AND status='created'").bind(id).run().catch(()=>{});return out({error:"MarzPay could not start this withdrawal. Your balance has not been debited; contact support before retrying if you received a payout prompt."},502)}}
if(p==="/api/requests"){let u=await me(req,e);if(!u)return out({error:"Not signed in"},401);let payments=(await e.DB.prepare("SELECT id,kind,amount_ugx,status,created_at FROM payment_requests WHERE user_id=? ORDER BY created_at DESC LIMIT 50").bind(u.id).all()).results||[];let purchases=(await e.DB.prepare("SELECT pp.id,pp.amount_ugx,pp.status,pp.created_at,p.name FROM product_purchases pp JOIN products p ON p.id=pp.product_id WHERE pp.user_id=? ORDER BY pp.created_at DESC LIMIT 50").bind(u.id).all()).results||[];let requests=payments.map(x=>({id:x.id,label:x.kind==="collection"?"Deposit":"Withdrawal",amount_ugx:x.amount_ugx,status:x.status,created_at:x.created_at})).concat(purchases.map(x=>({id:x.id,label:"Purchase · "+x.name,amount_ugx:x.amount_ugx,status:x.status,created_at:x.created_at}))).sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at))).slice(0,50);return out({requests})}
